x":23,"y":34},{"id":"ama-walk","kind":"npc_waypoint","x":21,"y":38},{"id":"kojo-park","kind":"npc_waypoint","x":28,"y":34},{"id":"kojo-walk","kind":"npc_waypoint","x":26,"y":40},{"id":"yaw-walk","kind":"npc_waypoint","x":32,"y":40},{"id":"esi-walk","kind":"npc_waypoint","x":40,"y":38},{"id":"abena-walk","kind":"npc_waypoint","x":38,"y":40},{"id":"abena-park","kind":"npc_waypoint","x":34,"y":35},{"id":"yaw-park","kind":"npc_waypoint","x":30,"y":36},{"id":"esi-park","kind":"npc_waypoint","x":35,"y":34}]},{"id":"apartment-interior","width":18,"height":14,"version":"5","blocked":[{"x":0,"y":0,"width":18,"height":1},{"x":0,"y":13,"width":18,"height":1},{"x":0,"y":0,"width":1,"height":14},{"x":17,"y":0,"width":1,"height":14},{"x":2,"y":2,"width":2,"height":2},{"x":5,"y":2,"width":1,"height":1},{"x":11,"y":3,"width":1,"height":1},{"x":11,"y":6,"width":2,"height":1},{"x":12,"y":7,"width":1,"height":1},{"x":12,"y":2,"width":3,"height":1},{"x":15,"y":2,"width":1,"height":1},{"x":4,"y":8,"width":2,"height":1},{"x":6,"y":10,"width":1,"height":1},{"x":3,"y":6,"width":1,"height":1},{"x":15,"y":9,"width":1,"height":1}],"spawns":[{"id":"apartment-spawn","kind":"door","x":9,"y":12},{"id":"apartment-default","kind":"player_default","x":9,"y":9},{"id":"apartment-home","kind":"npc_waypoint","x":6,"y":5}]}]'::jsonb)
as r(id text,width int,height int,version text,blocked jsonb,spawns jsonb);
update scenes s set width=r.width,height=r.height,asset_version=r.version::bigint,updated_at=now()
from professor_home_maps r where s.id=r.id;
update scenes set name='Professor Reed’s Home' where id='apartment-interior';
update buildings set display_name='Professor Reed’s Home' where id='building-apartment';
insert into spawn_points(id,scene_id,kind,x,y,facing)
select p.id,r.id,p.kind,p.x,p.y,'south' from professor_home_maps r
cross join lateral jsonb_to_recordset(r.spawns) as p(id text,kind text,x int,y int)
join scenes s on s.id=r.id
on conflict(id) do update set scene_id=excluded.scene_id,x=excluded.x,y=excluded.y,active=true;

create temporary table professor_home_routines on commit drop as
select * from jsonb_to_recordset('[{"id":"ama-morning","start":0,"end":450,"activity":"garden_walk","scene":"city-district","spawn":"ama-park","patrol":["ama-park","ama-walk"],"npc":"librarian-ama","sequence":0,"finish":450,"parameters":{"patrol":["ama-park","ama-walk"]}},{"id":"ama-library-morning","start":450,"end":720,"activity":"helping_readers","scene":"library-interior","spawn":"ama-library-desk","npc":"librarian-ama","sequence":1,"finish":720,"parameters":{}},{"id":"ama-lunch","start":720,"end":780,"activity":"cafe_break","scene":"cafe-interior","spawn":"ama-cafe-table","npc":"librarian-ama","sequence":2,"finish":780,"parameters":{}},{"id":"ama-library-afternoon","start":780,"end":1200,"activity":"helping_readers","scene":"library-interior","spawn":"ama-library-desk","npc":"librarian-ama","sequence":3,"finish":1200,"parameters":{}},{"id":"ama-evening","start":1200,"end":1440,"activity":"garden_walk","scene":"city-district","spawn":"ama-park","patrol":["ama-park","ama-walk"],"npc":"librarian-ama","sequence":4,"finish":1440,"parameters":{"patrol":["ama-park","ama-walk"]}},{"id":"yaw-morning","start":0,"end":510,"activity":"garden_walk","scene":"city-district","spawn":"yaw-park","patrol":["yaw-park","yaw-walk"],"npc":"quiz-attendant-yaw","sequence":0,"finish":510,"parameters":{"patrol":["yaw-park","yaw-walk"]}},{"id":"yaw-quiz-morning","start":510,"end":780,"activity":"hosting_quizzes","scene":"quiz-centre-interior","spawn":"yaw-quiz-desk","npc":"quiz-attendant-yaw","sequence":1,"finish":780,"parameters":{}},{"id":"yaw-break","start":780,"end":840,"activity":"park_break","scene":"city-district","spawn":"yaw-park","npc":"quiz-attendant-yaw","sequence":2,"finish":840,"parameters":{}},{"id":"yaw-quiz-afternoon","start":840,"end":1320,"activity":"hosting_quizzes","scene":"quiz-centre-interior","spawn":"yaw-quiz-desk","npc":"quiz-attendant-yaw","sequence":3,"finish":1320,"parameters":{}},{"id":"yaw-evening","start":1320,"end":1440,"activity":"garden_walk","scene":"city-district","spawn":"yaw-park","patrol":["yaw-park","yaw-walk"],"npc":"quiz-attendant-yaw","sequence":4,"finish":1440,"parameters":{"patrol":["yaw-park","yaw-walk"]}},{"id":"esi-morning","start":0,"end":330,"activity":"garden_walk","scene":"city-district","spawn":"esi-park","patrol":["esi-park","esi-walk"],"npc":"barista-esi","sequence":0,"finish":330,"parameters":{"patrol":["esi-park","esi-walk"]}},{"id":"esi-cafe-morning","start":330,"end":840,"activity":"working_counter","scene":"cafe-interior","spawn":"esi-cafe-counter","npc":"barista-esi","sequence":1,"finish":840,"parameters":{}},{"id":"esi-break","start":840,"end":900,"activity":"park_break","scene":"city-district","spawn":"esi-park","npc":"barista-esi","sequence":2,"finish":900,"parameters":{}},{"id":"esi-cafe-afternoon","start":900,"end":1380,"activity":"working_counter","scene":"cafe-interior","spawn":"esi-cafe-counter","npc":"barista-esi","sequence":3,"finish":1380,"parameters":{}},{"id":"esi-evening","start":1380,"end":1440,"activity":"garden_walk","scene":"city-district","spawn":"esi-park","patrol":["esi-park","esi-walk"],"npc":"barista-esi","sequence":4,"finish":1440,"parameters":{"patrol":["esi-park","esi-walk"]}},{"id":"kojo-morning","start":0,"end":480,"activity":"garden_walk","scene":"city-district","spawn":"kojo-park","patrol":["kojo-park","kojo-walk"],"npc":"resident-kojo","sequence":0,"finish":480,"parameters":{"patrol":["kojo-park","kojo-walk"]}},{"id":"kojo-walk","start":480,"end":540,"activity":"garden_walk","scene":"city-district","spawn":"kojo-park","patrol":["kojo-park","kojo-walk"],"npc":"resident-kojo","sequence":1,"finish":540,"parameters":{"patrol":["kojo-park","kojo-walk"]}},{"id":"kojo-reading","start":540,"end":720,"activity":"reading","scene":"library-interior","spawn":"kojo-library-reading","npc":"resident-kojo","sequence":2,"finish":720,"parameters":{}},{"id":"kojo-cafe","start":720,"end":780,"activity":"cafe_break","scene":"cafe-interior","spawn":"kojo-cafe-table","npc":"resident-kojo","sequence":3,"finish":780,"parameters":{}},{"id":"kojo-afternoon","start":780,"end":1080,"activity":"garden_walk","scene":"city-district","spawn":"kojo-park","patrol":["kojo-park","kojo-walk"],"npc":"resident-kojo","sequence":4,"finish":1080,"parameters":{"patrol":["kojo-park","kojo-walk"]}},{"id":"kojo-evening","start":1080,"end":1440,"activity":"garden_walk","scene":"city-district","spawn":"kojo-park","patrol":["kojo-park","kojo-walk"],"npc":"resident-kojo","sequence":5,"finish":1440,"parameters":{"patrol":["kojo-park","kojo-walk"]}},{"id":"abena-morning","start":0,"end":510,"activity":"garden_walk","scene":"city-district","spawn":"abena-park","patrol":["abena-park","abena-walk"],"npc":"student-abena","sequence":0,"finish":510,"parameters":{"patrol":["abena-park","abena-walk"]}},{"id":"abena-studying","start":510,"end":720,"activity":"studying","scene":"university-interior","spawn":"abena-university-desk","npc":"student-abena","sequence":1,"finish":720,"parameters":{}},{"id":"abena-cafe","start":720,"end":810,"activity":"cafe_break","scene":"cafe-interior","spawn":"abena-cafe-table","npc":"student-abena","sequence":2,"finish":810,"parameters":{}},{"id":"abena-walk","start":810,"end":1020,"activity":"garden_walk","scene":"city-district","spawn":"abena-park","patrol":["abena-park","abena-walk"],"npc":"student-abena","sequence":3,"finish":1020,"parameters":{"patrol":["abena-park","abena-walk"]}},{"id":"abena-reading","start":1020,"end":1200,"activity":"reading","scene":"library-interior","spawn":"abena-library-reading","npc":"student-abena","sequence":4,"finish":1200,"parameters":{}},{"id":"abena-evening","start":1200,"end":1440,"activity":"garden_walk","scene":"city-district","spawn":"abena-park","patrol":["abena-park","abena-walk"],"npc":"student-abena","sequence":5,"finish":1440,"parameters":{"patrol":["abena-park","abena-walk"]}}]'::jsonb)
as r(id text,npc text,sequence int,start int,finish int,activity text,scene text,spawn text,parameters jsonb);
delete from npc_schedules where npc_id in (select distinct npc from professor_home_routines);
insert into npc_schedules(id,npc_id,sequence,day_mask,start_minute,end_minute,activity,destination_scene_id,destination_building_id,destination_spawn_id,parameters)
select r.id,r.npc,r.sequence,127,r.start,r.finish,r.activity,r.scene,
case when r.scene='city-district' then null else 'building-'||replace(r.scene,'-interior','') end,r.spawn,r.parameters
from professor_home_routines r join spawn_points sp on sp.id=r.spawn and sp.scene_id=r.scene
left join buildings b on b.id='building-'||replace(r.scene,'-interior','')
where r.scene='city-district' or b.id is not null;

-- Preserve safe coordinates; recover positions and old paths outside the smaller home.
update player_presence p set
x=case when p.x<0 or p.y<0 or p.x>=r.width or p.y>=r.height or exists(
 select 1 from jsonb_to_recordset(r.blocked) as b(x int,y int,width int,height int)
 where p.x>=b.x and p.x<b.x+b.width and p.y>=b.y and p.y<b.y+b.height) then sp.x else p.x end,
y=case when p.x<0 or p.y<0 or p.x>=r.width or p.y>=r.height or exists(
 select 1 from jsonb_to_recordset(r.blocked) as b(x int,y int,width int,height int)
 where p.x>=b.x and p.x<b.x+b.width and p.y>=b.y and p.y<b.y+b.height) then sp.y else p.y end,
path='[]'::jsonb,path_index=0,scene_version=r.version::bigint,state_version=p.state_version+1
from professor_home_maps r,spawn_points sp
where p.scene_id=r.id and sp.scene_id=r.id and sp.kind='player_default';

-- Move only former housemates out immediately. The worker resumes their current routine.
update npc_runtime n set scene_id=case when n.scene_id='apartment-interior' then r.scene else n.scene_id end,
x=case when n.scene_id='apartment-interior' then sp.x else n.x end,
y=case when n.scene_id='apartment-interior' then sp.y else n.y end,
activity=case when n.scene_id='apartment-interior' then r.activity else n.activity end,
target_scene_id=null,target_spawn_id=null,target_x=null,target_y=null,state='{}'::jsonb,
last_simulated_at=null,state_version=n.state_version+1,updated_at=now()
from professor_home_routines r,spawn_points sp where n.npc_id=r.npc and r.sequence=0 and sp.id=r.spawn;
update npc_runtime n set x=sp.x,y=sp.y,target_scene_id=null,target_spawn_id=null,target_x=null,target_y=null,
state='{}'::jsonb,last_simulated_at=null,state_version=n.state_version+1,updated_at=now()
from spawn_points sp where n.npc_id='professor-kofi' and n.scene_id='apartment-interior' and sp.id='apartment-home';
update spawn_points set active=false where scene_id='apartment-interior' and id in ('ama-home','yaw-home','esi-home','kojo-home','abena-home');
